mapper.sql:
WHERE 1=1

AND m.owner_dept_id=#{q.ownerDeptId}
AND m.application_id=#{q.applicationId}
AND m.verification_type=#{q.type}
AND m.status=#{q.status}

FROM vi_driver_application a JOIN vi_driver_profile p ON p.id=a.driver_id JOIN vi_account account ON account.id=p.account_id JOIN sys_dept d ON d.dept_id=p.owner_dept_id AND d.status='0' AND d.del_flag='0' WHERE a.status IN ('DRAFT','REJECTED') AND NOT EXISTS(SELECT 1 FROM vi_driver_application newer WHERE newer.driver_id=a.driver_id AND newer.id>a.id) AND p.owner_dept_id=#{q.ownerDeptId}
AND p.owner_dept_id IN #{department}
AND 1=0

mapper.select:
SELECT COUNT(*) FROM vi_manual_verification
WHERE application_id=#{application} AND company_revision=#{epoch}
    AND material_revision=#{material} AND verification_type=#{type} AND status='PENDING_REVIEW'

mapper.update:
UPDATE vi_manual_verification
SET note_cipher=#{noteCipher}
WHERE id=#{id} AND status='PENDING_REVIEW' AND note_cipher IS NULL
